{
  "schemaVersion": "0.2",
  "slug": "select",
  "name": "Select",
  "status": "experimental",
  "purpose": "Presents a list of options in a collapsible menu that is keyboard and screen-reader accessible.",
  "scenarios": [
    "Choose a country or language from a long list",
    "Select a status in a form",
    "Navigate options with the keyboard"
  ],
  "props": {
    "value": {
      "type": "string",
      "required": true,
      "description": "Controlled selected value."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Receives the next selected value.",
      "payload": "(value: string) => void"
    },
    "options": {
      "type": "string",
      "required": true,
      "description": "Array of option objects with value and label."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name for the select."
    },
    "placeholder": {
      "type": "string",
      "required": false,
      "description": "Text shown when no option is selected.",
      "default": "Select an option"
    },
    "disabled": {
      "type": "boolean",
      "required": false,
      "description": "Prevents opening the listbox.",
      "default": false
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Idle and selectable."
    },
    {
      "name": "disabled",
      "description": "Cannot be opened or changed."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "dialog",
      "field-group"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a select for only two options; consider a radio group.",
    "Do not remove the visible label."
  ],
  "a11y": {
    "role": "combobox",
    "keyboard": [
      "Enter/Space opens the listbox",
      "Arrow keys move highlight",
      "Enter selects"
    ],
    "focus": "Trigger is focusable; focus moves into the listbox when opened.",
    "labeling": "Visible label is associated with the combobox.",
    "wcag": [
      "1.3.1",
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "The trigger stretches to the parent inline size. The listbox is positioned absolutely and stays within the viewport.",
    "breakpoints": {
      "compact": "Full inline size of the parent; listbox uses available space.",
      "medium": "Content or parent width.",
      "large": "Content or parent width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir; listbox opens in the flow direction.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "select",
    "states": [
      "default",
      "disabled"
    ],
    "intents": [
      "choose-option"
    ]
  },
  "mechanics": "Select is a labeled listbox. value and onChange are required (controlled). options is an array of { value, label }. Keyboard and screen-reader behavior come from the primitive; CSS does not replace the listbox with a native select.",
  "usage": [
    "Import Select from @chameleon-ui/components.",
    "Pass label, options, value, and onChange. Keep the selected value in React state.",
    "Set disabled while options are loading. Do not use placeholder as the only label."
  ],
  "exports": [
    {
      "name": "Select",
      "kind": "component",
      "signature": "function Select(props: SelectProps): JSX.Element",
      "description": "Accessible listbox with value, onChange, options, and label."
    },
    {
      "name": "SelectProps",
      "kind": "type",
      "signature": "interface SelectProps",
      "description": "Public props including options: Array<{ value, label }>."
    }
  ]
}

import { SelectPrimitive } from '@chameleon-ui/primitives'
import { useMemo } from 'react'
import './styles.css'

export interface SelectOption {
  value: string
  label: string
}

export interface SelectProps {
  value: string
  onChange: (value: string) => void
  options: SelectOption[]
  label: string
  placeholder?: string
  disabled?: boolean
  className?: string
}

export function Select({
  value,
  onChange,
  options,
  label,
  placeholder = 'Select an option',
  disabled = false,
  className,
}: SelectProps) {
  const collection = useMemo(() => SelectPrimitive.createListCollection({ items: options }), [options])
  const classes = ['cu-select', className].filter(Boolean).join(' ')

  return (
    <SelectPrimitive.Root
      className={classes}
      collection={collection}
      data-ai-role="select" data-ai-intent="choose-option"
      data-ai-state={disabled ? 'disabled' : 'default'}
      disabled={disabled}
      value={[value]}
      onValueChange={(details) => onChange(details.value[0] ?? '')}
    >
      <SelectPrimitive.Label className="cu-select__label">{label}</SelectPrimitive.Label>
      <SelectPrimitive.Control>
        <SelectPrimitive.Trigger className="cu-select__trigger">
          <SelectPrimitive.ValueText placeholder={placeholder} />
          <SelectPrimitive.Indicator className="cu-select__indicator">▼</SelectPrimitive.Indicator>
        </SelectPrimitive.Trigger>
      </SelectPrimitive.Control>
      <SelectPrimitive.Positioner className="cu-select__positioner">
        <SelectPrimitive.Content className="cu-select__content">
          <SelectPrimitive.List className="cu-select__list">
            {options.map((option) => (
              <SelectPrimitive.Item
                key={option.value}
                className="cu-select__item"
                item={option}
              >
                <SelectPrimitive.ItemText>{option.label}</SelectPrimitive.ItemText>
                <SelectPrimitive.ItemIndicator className="cu-select__item-indicator">✓</SelectPrimitive.ItemIndicator>
              </SelectPrimitive.Item>
            ))}
          </SelectPrimitive.List>
        </SelectPrimitive.Content>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Root>
  )
}

.cu-select {
  display: inline-block;
}

.cu-select__label {
  display: block;
  color: var(--cu-color-fg-default);
  font-size: 0.82rem;
  font-weight: 700;
  margin-block-end: var(--cu-space-1);
}

.cu-select__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  min-inline-size: 10rem;
  min-block-size: 2.75rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
  font: inherit;
  cursor: pointer;
  gap: var(--cu-space-2);
}

.cu-select__trigger:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

.cu-select__trigger:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.cu-select__indicator {
  font-size: 0.75rem;
}

.cu-select__content {
  background: var(--cu-color-background-default);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  box-shadow: var(--cu-shadow-md);
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-1);
}

.cu-select__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-select__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-block-size: 2.25rem;
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border-radius: var(--cu-radius-sm);
  cursor: pointer;
  gap: var(--cu-space-2);
}

.cu-select__item[data-highlighted] {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 12%, transparent);
}

.cu-select__item-indicator {
  inline-size: 1rem;
  text-align: center;
  visibility: hidden;
}

.cu-select__item[data-state='checked'] .cu-select__item-indicator {
  visibility: visible;
}

@media (prefers-reduced-motion: reduce) {
  .cu-select__indicator,
  .cu-select__item {
    transition-duration: 0.01ms;
  }
}
